import json
word = [0, 1, 0, 2, 3, 1, 3, 2]
def seg(prefix):
    pend = []
    for s in prefix:
        if s in (0, 1):
            pend.append(s)
        else:
            pend.pop()
    return pend[-1] if pend else -1
Phi = {0: 2, 1: 3}
outs = []
for t in range(1, len(word) + 1):
    tag = seg(word[:t])
    if tag >= 0:
        outs.append(Phi[tag])
print(json.dumps({"closers": outs, "count": len(outs)}))
